INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('bedrock-nethernet', 1793059200000, 'server', NULL, 'Bedrock players keep joining through the protocol change', 'Bedrock Edition switched to a new connection method today — the server already speaks it, and your join details do not change.', '{"keyChanges":["Bedrock moved every player to a new connection method (NetherNet) today; the old one stops working for updated clients.","The server was moved to the newest translation build ahead of the switch and now accepts both the new method and the old one, so every Bedrock version in the supported range can join.","Your join details are unchanged: play.romanica.net, port 19132, for Java and Bedrock alike.","On a newer Bedrock version you may see a one-time prompt asking whether you trust the server on your first join. That is expected and safe — accept it and play as usual.","Bedrock versions 26.30 and older are no longer supported; update your game if you are on one of those.","The translation layer and its account bridge both run their latest builds, so console and phone players get the newest fixes."],"tags":["bedrock","crossplay","compatibility"],"action":"Nothing to change — join as always at play.romanica.net, port 19132.","readHref":"/wiki/bedrock"}', '{}', '[]', NULL)
