INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('store-link-rank-protection-anticheat', 1793059200000, 'server', NULL, 'Store link restored, your rank protected, sharper anticheat', 'The in-game store link works again, a rare sign-in hiccup can no longer reset your rank, and going through thin blocks is now caught.', '{"keyChanges":["The web-store link inside /store and the scoreboard links now open romanica.net — they still pointed at the retired address, so the store page would not load.","A rare server-side hiccup during sign-in could reset a player’s rank to 1 and save it. Failed rank loads are now retried and, if they still fail, discarded instead of saved.","A background maintenance task could stall permanently after a database hiccup until the next restart; it now recovers on its own.","A malformed response during a routine license check could disconnect every player; the server now treats it as a temporary network error.","/vote all no longer lists vote websites that have shut down — only live listings remain.","Going through thin blocks such as glass panes and iron bars is now detected. The old check measured depth in a way thin blocks could never reach, so those walls were effectively unguarded.","Bedrock players keep their burst-mining allowance, but the sustained mining rate now matches Java players instead of sitting 2.5x higher.","Twelve NPCs had a latent setup issue that would have dropped their custom skins; fixed before it could show."],"tags":["store","ranks","anticheat","fixes"]}', '{}', '[]', NULL)
