INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('sign-in-with-microsoft', 1792800000000, 'website', NULL, 'Sign in with Microsoft', 'The website now accepts the Microsoft account that owns your Minecraft account — no password entered here, ever.', '{"keyChanges":["A new Microsoft option sits alongside Discord and the in-game code on the login page.","Signing in proves it is really you through Microsoft itself, using the same account the game and the Romanica launcher use.","You land straight in your dashboard, with your Discord link attached automatically if you have one."],"tags":["login","microsoft"],"action":"Try it: romanica.net/login, choose Microsoft."}', '{}', '[]', NULL)
