INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('launcher-0-2-7', 1792800000000, 'launcher', '0.2.7', 'Launcher 0.2.7: supported engine, clean security slate', 'The launcher moves to a fully supported desktop engine with every known dependency advisory cleared, and the launch screen now tracks the real work.', '{"keyChanges":["Runs on a fully supported version of its desktop engine, with all 29 known dependency security findings cleared.","The launching screen tracks the real work — file checks run in parallel and progress follows the game’s own log.","Development-kit installs verify cleanly from scratch again."],"tags":["launcher","security"],"action":"Restart the launcher — it updates itself."}', '{}', '[]', NULL)
