INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('cassius-guide-at-spawn', 1792713600000, 'server', NULL, 'A guide now waits at the gates of Rome', 'Cassius the Fixer stands in the heart of Rome, ready to walk newcomers through their first hour.', '{"keyChanges":["Cassius the Fixer is placed near the spawn point. Right-click him and he offers a guided tour: the Mine, the coins it pays, and the enchantments that multiply both.","Already know your way around? Tell him to skip the tour and he leaves you to it."],"tags":["story","new-players"],"action":"Look for Cassius near the spawn fountain and say hello."}', '{}', '[]', NULL)
