INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('honest-store-page', 1792713600000, 'website', NULL, 'An honest store page', 'Store tiers no longer advertise an auto-sell perk that never actually worked.', '{"keyChanges":["Store tiers no longer list an auto-sell perk — it never worked and was removed from the game long ago. Taglines show only what each tier really includes.","The perks page now describes the real benefit: a discount on the fee for selling."],"tags":["store"]}', '{}', '[]', NULL)
