INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('launcher-0-2-6', 1792713600000, 'launcher', '0.2.6', 'Launcher 0.2.6: disk cleanup and crash privacy', 'The launcher stops hoarding old client versions, and crash reports are scrubbed before they leave your PC.', '{"keyChanges":["Old client versions are cleaned up after updating - every version ever downloaded used to stay on your disk forever.","Crash reports are scrubbed before sending: usernames in file paths and any tokens or secrets are removed, stack traces stay for diagnosis.","Fixed a bug where about half the mod files saved with ‘undefined’ in their filename."],"tags":["launcher"],"action":"Restart the launcher - it updates itself."}', '{}', '[]', NULL)
