INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('romanica-name-everywhere', 1792713600000, 'server', NULL, 'The Romanica name, everywhere it reaches you', 'The last user-facing spots that still said the old name now say Romanica - in all 45 game languages.', '{"keyChanges":["Welcome messages, broadcasts and menus now say Romanica in every one of the game’s 45 languages.","The website’s guide pages now point at the right settings files.","A routine security sweep updated the server’s supporting libraries."],"tags":["romanica","security"]}', '{}', '[]', NULL)
