INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('client-beta-24-breadcrumbs', 1792713600000, 'client', '0.2.0-beta.24', 'Romanica Client beta.24: breadcrumbs fixed', 'Legion breadcrumbs stay on screen again — a slip two versions back made them vanish within a second.', '{"keyChanges":["Legion breadcrumbs work again — a slip introduced two client versions ago made every crumb vanish within a second of dropping it.","The client updates itself through the launcher the next time you launch it — nothing to do by hand."],"tags":["client","legion"]}', '{}', '[]', NULL)
