INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('store-leaderboard-guides-polish', 1792713600000, 'website', NULL, 'A cleaner store, leaderboard and guides', 'The shopping, rankings and community-guides pages got a craft pass — and two real glitches were fixed along the way.', '{"keyChanges":["The leaderboards read properly now: labeled columns, neatly aligned numbers, a cleaner top-three podium and a highlight when you point at a row.","Store pages line up — the tier comparison table and perk prices use properly aligned figures, and the tier-page questions sit in tidy cards instead of a bare stack.","The community guides page was rebuilt in the same style as the rest of the site, with working filters and sort chips.","Fixed a garbled hover label on blog cards, and corrected an outdated statistic on the features page.","FAQ category icons now render the same on every system."],"tags":["website","store","leaderboards"]}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
