INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('legion-commands-and-navy-map', 1792713600000, 'server', NULL, 'Legion commands and a navy live map', 'The legion command family got native tab completion, and the live map now matches the rest of the site.', '{"keyChanges":["Typing /legion (and its roughly forty subcommands) now suggests and tab-completes natively, same for about thirty more everyday commands including tips, scoreboard, rename, broadcast, mute and the gamemode shortcuts.","The live map’s headers, side panels and gazetteer were retuned from near-black to the same deep navy as the rest of the site — the map itself, its markers and colours are unchanged.","Staff pages behind the admin dashboard were moved onto the same navy palette."],"tags":["commands","legion","map","theme"],"action":"Type /legion and press Tab in-game to see the new suggestions."}', '{}', '[]', NULL)
