INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('site-wide-polish-pass', 1792627200000, 'website', NULL, 'A sharper website, head to toe', 'Every page now uses the emblem’s exact gold and navy, with cleaner cards, buttons and navigation.', '{"keyChanges":["Borders, glows and buttons across every page — the store, the wiki, the map, your dashboard — now use the emblem’s champagne gold instead of the older, muddier shade they still carried.","The active page button in the navigation is easier to spot, and the top bar sits on a cleaner deep-navy backdrop.","Keyboard focus rings, text selection and scrollbars are themed to match, and animations settle down for visitors who prefer reduced motion.","The live map’s markers, compass and buttons were retuned to the same palette, so it no longer reads like a different site."],"tags":["website","theme","map","store"]}', '{}', '[]', NULL)
