INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('romanica-net-live-store-fixed', 1792627200000, 'website', NULL, 'romanica.net is live, store fixed, new look', 'The new address is live end to end, checkout works there, and everything now matches the emblem.', '{"keyChanges":["The website now lives at romanica.net, and the server address is play.romanica.net - the old address keeps working.","Checkout on romanica.net is fixed - purchases were being blocked by a security check that only knew the old address.","The launcher (0.2.3) has new background art and emblem-matched colors, and connects through play.romanica.net.","The client (0.2.0-beta.14) interface matches the emblem: deep-navy surfaces with champagne-gold accents."],"tags":["romanica-net","store","launcher","client"],"action":"Open the launcher and both it and the client update by themselves."}', '{}', '[]', NULL)
