INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('faster-joins-smoother-onboarding', 1792627200000, 'server', NULL, 'Faster joins and smoother onboarding', 'The texture pack is remembered between joins, and holding right-click with tools no longer trips cheat detection.', '{"keyChanges":["The texture pack downloads once and is remembered - returning players join in about a second instead of re-downloading a large file every single time.","The pack is also no longer sent twice per join.","Holding right-click with your pickaxe or other tools while looking around no longer trips cheat detection - it was wrongly flagging and even freezing brand-new accounts during their first minutes.","Players joining through launcher or controller setups no longer build up cheat-detection penalties from a large startup handshake - the extra traffic it generated was wrongly counted against the player.","Tab completion and command suggestions now work natively on more of the everyday commands, including kit, casino, vault, trade, mail, marriage, parkour, and loadouts."],"tags":["performance","anticheat","commands"],"action":"Nothing to do - everything applies the next time you join."}', '{}', '[]', NULL)
