INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('romanica-new-emblem', 1792627200000, 'website', NULL, 'A new emblem for Romanica', 'A gold-ringed eagle medallion now stands for Romanica everywhere.', '{"keyChanges":["The new emblem - a gold-ringed eagle medallion on deep navy - replaces the old mark everywhere: this site and its browser icons, the launcher, the client, the server list, and Discord.","Launcher 0.2.2 carries the emblem on the app, the installer, and the loading screen - existing installs update themselves.","Client 0.2.0-beta.13 shows the emblem in your mod list and as the badge next to player names in-game."],"tags":["branding","launcher","client"],"action":"Open the launcher once and both it and the client update by themselves."}', '{}', '[]', NULL)
