INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('romanica-client-beta12', 1792627200000, 'client', '0.2.0-beta.12', 'Romanica Client beta.12', 'Secure sign-in groundwork: the client proves who you are with the same handshake Minecraft uses for servers.', '{"keyChanges":["No passwords to enter and nothing stored on your disk - the sign-in uses the game''s own session, the same one used when joining an online server.","Your legion''s name and standing will display on the HUD even on other servers, once the account services switch on.","Everything degrades gracefully - if the services are unavailable, nothing changes and nothing breaks."],"tags":["update","client"],"action":"Open the launcher and the client updates by itself.","readHref":"/client"}', '{}', '[]', NULL)
