INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('romanica-client-beta11', 1792540800000, 'client', '0.2.0-beta.11', 'Romanica Client beta.11', 'The clean look: menu backdrop blur, a proper UI typeface, themed buttons, and the rebuilt HUD editor.', '{"keyChanges":["The client menu softly blurs the world behind it - the signature look of a modern client, respecting the game''s own blur setting.","A proper UI typeface for labels, smooth hover and press motion on every card, button and chip, and a real item icon on every module card.","The HUD editor is rebuilt: snap guides with a live position readout, selection handles, arrow-key nudging with undo and redo, a right-click menu with reset, hide and an anchor picker, plus a toolbar and help panel.","The launcher matches the client exactly - same colors, one consistent hover, press and keyboard-focus system, smoother typography."],"tags":["update","client"],"action":"Open the launcher and both update by themselves.","readHref":"/client"}', '{}', '[]', NULL)
