INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('romanica-rename', 1792540800000, 'website', NULL, 'ImperiumMC is now Romanica', 'New name, same Rome. Your account, rank, balance and files all carry over - and our new address romanica.net goes live as soon as the domain is ready.', '{"keyChanges":["The website, the launcher (Romanica Launcher 0.2.0), the client (Romanica Client), the Discord bot and every in-game message carry the new name.","Nothing you own changes: accounts, ranks, balances, plots and client settings carry over automatically; the launcher picks up your existing files on first start.","The new address romanica.net is announced the moment it works - until then, connect exactly as you do today.","Launcher 0.2.0 also fixes the server address shown in the launcher''s server list, which had pointed at a wrong domain."],"tags":["announcement"],"action":"Open the launcher and everything updates by itself.","readHref":"/client"}', '{}', '[]', NULL)
