INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('imperium-client-beta9', 1792540800000, 'client', '0.2.0-beta.9', 'Romanica Client beta.9', 'Performance options with measured results, and the client now speaks three more languages.', '{"keyChanges":["A text render distance option cuts frame time nearly in half in sign- and hologram-heavy scenes (measured at minus 45 percent with 28 signs and name tags on screen).","A HUD frame cache paces HUD redraws - cost-neutral on fast machines, helpful for item-heavy HUDs on slower CPUs.","Optional toggles skip TNT''s flash expansion, spawner internals and enchant-table books for a little more headroom.","The menu, module names and key messages now follow your game language in Portuguese, German and Spanish."],"tags":["update","client"],"action":"Open the launcher and the update installs by itself.","readHref":"/client"}', '{}', '[]', NULL)
