INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('imperium-client-beta8', 1792454400000, 'client', '0.2.0-beta.8', 'Romanica Client beta.8', 'The full Romanica redesign of the title screen and module menu, and live server data in your HUDs.', '{"keyChanges":["A new title screen: the emblem, the wordmark, and a Play button that shows the live player count.","The module menu is rebuilt: sliding sidebar, three-column cards with real item icons, and a clear red state for anything the server keeps locked.","Settings rows refined to match - section accents, hover highlighting, reset buttons, half-width pairs.","Live server data reaches the HUDs directly: your legion''s power and online count, active boosts with remaining time, and server cooldowns like rifts.","Mine regions draw in the world for client users, showing exactly where your current mine ends."],"tags":["update","client"],"action":"Open the launcher and everything updates by itself.","readHref":"/client"}', '{}', '[]', NULL)
