INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('imperium-client-beta7', 1792454400000, 'client', '0.2.0-beta.7', 'Romanica Client beta.7', 'The client wears the Romanica emblem on every surface, the titles HUD keeps its colors, and the core is now Kotlin.', '{"keyChanges":["The mod-list icon, the title and pause menu buttons, and the in-game menu all show the Romanica seal from the website.","Fixed: titles a server sends now keep their colors and long titles wrap to fit instead of clipping off screen.","The client core - menu, server integration, rules enforcement - is rewritten in Kotlin; invisible to players, faster feature work ahead."],"tags":["update","client"],"action":"The launcher updates the client automatically - open it and you are up to date.","readHref":"/client"}', '{}', '[]', NULL)
