INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('launcher-0-1-2', 1792454400000, 'launcher', '0.1.2', 'Launcher 0.1.2', 'The launch crash is fixed, every download is hash-verified before the game starts, and a crash screen shows the cause.', '{"keyChanges":["Fixed the crash some players hit on launch: the game''s library files now unpack to the exact folders Minecraft looks in.","Every file the launcher downloads is checked against its published hash; a corrupted download repairs itself instead of launching broken.","When the game closes with an error, the launcher shows the cause with a Copy report button for Discord support.","The news panel works, reading the site''s news feed."],"tags":["fix","launcher"],"action":"The launcher updates itself - open it to get the fixes.","readHref":"/client"}', '{}', '[]', NULL)
