INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('launcher-0-1-1', 1792454400000, 'launcher', '0.1.1', 'Launcher 0.1.1', 'The launcher now wears the Romanica emblem, and Microsoft login is confirmed working for everyone.', '{"keyChanges":["The app icon, the welcome and login screen, and the loading screen all show the same Romanica seal you know from the website.","Microsoft login is confirmed working - any earlier approval notice is gone, and sign-in opens normally."],"tags":["update","launcher"],"action":"The launcher updates itself - open it and 0.1.1 installs automatically.","readHref":"/wiki/getting-started"}', '{}', '[]', NULL)
