INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('imperium-client-beta6', 1792454400000, 'client', '0.2.0-beta.6', 'Romanica Client beta.6', 'Module settings open inside the menu, HUD elements can blur the world behind them, and a performance section arrives.', '{"keyChanges":["The gear on any module card now opens that module''s settings right inside the menu as a scrollable panel - every option one click away, with labelled groups for sub-options, and Escape returns you straight to the module grid.","Every HUD element can blur the world behind its background for a soft frosted look - on per element, with adjustable strength.","A new Performance section: a frame limiter that can lower FPS while the window is minimized, unfocused, or while you are away (off by default, and it always respects the game''s own throttling when that is stricter), plus visibility toggles for the TNT flash, lightning bolts, dropped hopper items and distant entities.","Chunk borders and the hitboxes view now draw reliably every frame instead of only appearing at certain times.","The account card no longer appears in the module grid; account settings stay under All Settings."],"tags":["update","client"],"action":"The launcher updates the client automatically - open it and you are up to date.","readHref":"/wiki/getting-started"}', '{}', '[]', NULL)
