INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('imperium-client-beta5', 1792368000000, 'client', '0.2.0-beta.5', 'Romanica Client beta.5', 'Every remaining gap in the module lineup is closed - TNT arcs, a fullscreen map, light levels, and more.', '{"keyChanges":["TNT trajectory preview: hold a TNT and see exactly where it will fly and how big the blast will be before you throw it.","A fullscreen map on M - pan around, zoom in and out, and see every waypoint with its name and distance.","Light-level overlay on F7: the ground lights up green where mobs cannot spawn and red where they can.","Waypoint tracers: every waypoint shows as an on-screen marker with its name and distance, with arrows when it is off-screen.","Chat upgrades: smooth scrolling, history that survives relogging, a screenshot button for just the chat, and three quick-phrase keybinds.","Inventory upgrades: hide the potion icons, keep your inventory perfectly centred, and compact stack counts.","Hitboxes on a keybind - player, mob and item boxes with eye lines, without the F3 screen.","An emote wheel on hold-G with wave, salute, cheer and sit built in, ready for server cosmetics.","A Now Playing HUD that shows your current Spotify track while you play."],"tags":["announcement","client"],"action":"Grab the launcher from the Discord - it installs and updates everything for you.","readHref":"/wiki/getting-started"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
  related=excluded.related, synced_at=excluded.synced_at;

INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('imperium-client-beta2', 1792368000000, 'client', NULL, 'Romanica Client and the official launcher', 'Our own client and launcher are here - everything installs in one click and stays updated automatically.', '{"keyChanges":["A minimap with real terrain colours and hill shading - square or round, rotates with your camera or locks north, and your waypoints appear on it as labelled dots.","Waypoints: press B to drop one anywhere, see name, direction and distance on your HUD, and get an automatic marker where you died so you can find your way back.","A legion status readout, breadcrumbs (press N to drop a trail marker), and TNT blast-radius boxes that show exactly what a primed TNT is about to hit.","Chat upgrades: timestamps, a sound ping when someone says your name, duplicate messages stacking as a counter, a hold-to-peek key for recent history, and empty spam filtered out.","The tab list shows real ping numbers in colour and highlights your own row; any chest or inventory gets a search bar that lights up matching items.","A bundle of HUD and comfort options: movable titles, item cooldown bars, playtime/stopwatch/entity/potion/obsidian counters, armor durability colours, potion blink, TNT timer stages, particle control, hurt-camera control, low-health screen tint, clear water, crop growth overlays, chunk borders, and a 180-degree quick-look key.","WorldEdit users: selections render as the classic grid box in the world.","The official Romanica Launcher installs everything in one click - Minecraft 26.3, Fabric, Romanica Client and the performance mods - and verifies every file on every start. Updates arrive automatically on the next launch."],"tags":["announcement","client"],"action":"Grab the launcher from the Discord - it installs everything for you.","readHref":"/wiki/getting-started"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
