INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('story-guidance-mine-restoration', 1792195200000, 'server', NULL, 'Story guidance catches up with the mine restoration', 'The opening story line and the compass targets for Titus, Lucia and Gaius now match the world as it is today.', '{"keyChanges":["The first-chapter arrival line told new players to warp straight into the mines - impossible while every mine is closed for the hand restoration. It now points at your compass and says the mines will guide you again when they reopen.","Compass wayfinding to the story NPCs Titus, Lucia and Gaius was resolving to authored placeholder coordinates instead of their real positions. The compass now leads to where those three actually stand.","Titus, Lucia and Gaius dropped the decorative symbols from their name tags - on vanilla-font and Bedrock clients those symbols rendered as empty boxes."],"tags":["story","quality"],"action":"Mid-story already? Your compass to Titus, Lucia or Gaius now points at the real NPC.","readHref":"/wiki/getting-started"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
  related=excluded.related, synced_at=excluded.synced_at;

INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('mine-restoration-underway', 1792195200000, 'server', NULL, 'Mine restoration underway', 'Every mine is being rebuilt by hand, so all automatic refills and block generation are paused until the restoration is finished.', '{"keyChanges":["All automatic mine refills and block generation are paused while every mine is rebuilt by hand - nothing will place, replace, or fill blocks in any mine until the restoration is done.","Mines are temporarily closed while their pits are restored - warping to one will tell you to check back soon.","When each mine reopens it will refill with fresh ore exactly as before."],"tags":["announcement","progression"],"action":"Mines reopen as each one is restored - watch the Discord for the announcement.","readHref":"/wiki/getting-started"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
  related=excluded.related, synced_at=excluded.synced_at;

INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('objective-bar-always-on', 1792195200000, 'server', NULL, 'The game now always tells you what to do next', 'The objective bar above your hotbar now stays with you every session and always names the single most useful thing to do right now.', '{"keyChanges":["The OBJECTIVE bar used to disappear after your very first session on the server - now it is there every time you play, pointing at your best next step.","It leads with what you would otherwise miss: finished daily quest or battle pass rewards waiting to be claimed, crate keys sitting unopened, your current story step with live progress, and a rank up the moment you can afford it.","Saving for a rank now has a live target: \"Rank VII - 8.4k to go\", counting down as you mine and sell instead of a vague \"go mine\".","When something becomes ready - rewards to claim, a rank you can pay for - you get one short chat heads-up, so the bar being easy to ignore no longer matters.","/next still prints the same guidance in full chat detail any time you want it - the bar and the command can never disagree because they share one brain."],"tags":["progression","quality"],"action":"Look above your hotbar when you log in - the OBJECTIVE line is your next step. Type /next for the full version.","readHref":"/wiki/getting-started"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
  related=excluded.related, synced_at=excluded.synced_at;

INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('bug-report-command', 1791936000000, 'server', NULL, 'Reporting a bug now takes one command', '/bug is live: describe what happened, and it lands directly in the queue the devs read every day.', '{"keyChanges":["Type /bug <what happened, and what you expected> - that is it. Where you are, your rank, the server version and how many players are online are captured automatically, so you never have to explain where you were.","Your report goes straight to a queue the devs read every single day - no Discord ticket, no waiting for a staff member to be online.","Reports are limited to one every two minutes per player, which keeps the queue clean so every report actually gets read.","Also this week: the economy monitor no longer flags quest rewards as suspicious, and background jobs can no longer crowd out logins during busy minutes."],"tags":["quality","community"],"readHref":"/support"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
  related=excluded.related, synced_at=excluded.synced_at;

INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('discord-bot-three-new-commands', 1791763200000, 'server', NULL, 'The Discord bot learned three new tricks', 'The Romanica bot got its biggest upgrade in months - new lookup commands, a cleaner look, and the full update history at your fingertips.', '{"keyChanges":["/mine - look up any mine by numeral (XLVIII), name (Marcus Aurelius) or number (48): its unlock rank, every ore it holds with the denarius each block pays, and its signature ores.","/changelog - the five latest server updates right in Discord, with the full per-update history right here on this page.","/vote - every vote link and exactly what voting pays you, in one reply.","Every bot reply is restyled to the bronze-and-marble look of the new emblem, and the symbols that rendered as garbage on some clients are gone for good."],"tags":["discord","bot"],"readHref":"/wiki/commands"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
