INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('last-two-frozen-mines-open', 1791676800000, 'server', NULL, 'The last two frozen mines are open, all fifty await', 'The Augustan Forum Mine and the Marcus Aurelius Memorial passed their repairs and inspection, completing the ladder from Mine I to the Golden Milestone.', '{"keyChanges":["The Augustan Forum Mine (Rank 41) and the Marcus Aurelius Memorial (Rank 48) were held back from the big expansion because their entry points dropped you into the floor instead of onto it.","Their entry platforms are fixed and both mines passed a block-by-block inspection of the whole dig site before opening — the ore in them is the real, full table, verified at every corner of the region.","Every mine from I to L is now enterable: fifty in total, the complete ladder up to the Golden Milestone at Rank 50. Deeper mines keep paying richer ore, exactly as the ladder promises."],"tags":["mines","progression"],"readHref":"/progression"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
  related=excluded.related, synced_at=excluded.synced_at;

INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('faster-website-honest-map', 1791676800000, 'website', NULL, 'A faster website, an honest map, and proper link cards', 'The website got a full speed pass, the live map can no longer get stuck showing an old copy, and sharing Romanica links now shows a proper card.', '{"keyChanges":["Pages you visit often now open almost instantly — they are kept ready on a server near you instead of being rebuilt from scratch every time.","The live player counter on the homepage no longer pauses to check the server; it refreshes without the wait, and images ship in a much lighter format, which you will notice most on a phone.","If the live map ever looked broken, empty or stuck in the past for you, your browser was replaying an old saved copy of it. The map now forces a fresh load every visit, so that cannot happen again.","Posting a Romanica link on Discord or socials now shows a proper Romanica card — emblem, title and all — instead of a gray rectangle."],"tags":["website","performance","map"],"readHref":"/"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
