INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('site-speaks-three-languages', 1791590400000, 'website', NULL, 'The website now speaks Portuguese, German and Spanish', 'The landing pages are available in three more languages, picked automatically from your browser, with a switcher in the footer.', '{"keyChanges":["The homepage, the vote page, the beginner guide and the FAQ are now available in Brazilian Portuguese, German and Spanish.","Your browser picks the right language automatically on first visit, and a language switcher sits in the site footer — English always stays at imperiummc.net.","The landing pages also lost their last bits of template filler, including the old scroll hint."],"tags":["website","languages"],"readHref":"/pt-BR"}', '{}', '[]', NULL)
