INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('frozen-mine-band-opens', 1791590400000, 'server', NULL, 'The Sabine Ridge and beyond: 22 new mines open', 'The biggest expansion since launch — 22 new mines from Rank 27 to Rank 50, each one ground-verified before opening.', '{"keyChanges":["Twenty-two new mines opened in one release, stretching from The Sabine Ridge at Rank 27 to The Golden Milestone at Rank 50.","Every site was checked on the ground before unlocking — entry points, ore fills and floors were verified mine by mine, and anything that failed stayed closed for repairs.","Two sites (the Augustan Forum Mine and the Marcus Aurelius Memorial) stayed closed for entry-point repairs and passed inspection the next day; seven more wait beyond the Milestone for the next release."],"tags":["mines","progression"],"readHref":"/progression"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
  related=excluded.related, synced_at=excluded.synced_at;

INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('263-clients-and-lighter-mobile-data', 1791590400000, 'server', NULL, 'Minecraft 26.3 clients welcome, lighter data on mobile', 'Newer Java editions can join directly, Bedrock support runs on the newest translation build, and phones download less.', '{"keyChanges":["Minecraft 26.3 clients can now join — the cross-version layer accepts every newer Java edition on the 26.2 server.","Bedrock support runs on the newest translation build, covering the latest console and phone Bedrock versions.","Data use on mobile is lighter across the board, from the resource pack to how much the client fetches while you play."],"tags":["compatibility","bedrock"],"readHref":"/wiki/getting-started"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
