INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('smoother-first-minutes-on-touch', 1791417600000, 'server', NULL, 'Smoother first minutes on touch and new accounts', 'Playing on touchscreens no longer trips the cheat detection, and new accounts get a fair learning window before anything can count against them.', '{"keyChanges":["Fast touch mining no longer trips the cheat detection anywhere on the map — not just inside mines.","Tapping beds and chests through doorways now works reliably instead of sometimes being read as reaching through walls.","The adaptive detector now learns your personal style for ten minutes before it can flag anything — your opening moments on a new account no longer count against you."],"tags":["bedrock","fairness","anticheat"],"readHref":"/wiki/bedrock"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
  related=excluded.related, synced_at=excluded.synced_at;

INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('faster-joins-during-busy-periods', 1791244800000, 'server', NULL, 'Faster joins during busy periods', 'A wave of players logging in at once no longer stalls everyone — joins got their own dedicated handling.', '{"keyChanges":["When many players logged in at the same moment — restarts, vote pushes, events — each join competed for the same thread of work as everything else, and everyone felt the stall.","Joins now run on their own dedicated handling, so a busy login rush processes in parallel instead of forming a queue that delays the whole server.","You will notice this most right after a restart or during a drop party: getting in is fast no matter how many others are arriving with you."],"tags":["connection","performance"],"readHref":"/wiki/getting-started"}', '{}', '[]', NULL)
ON CONFLICT(id) DO UPDATE SET date=excluded.date, product=excluded.product, version=excluded.version,
  title=excluded.title, summary=excluded.summary, body=excluded.body, links=excluded.links,
