INSERT INTO changelog_entry (id, date, product, version, title, summary, body, links, related, synced_at)
VALUES ('praeneste-shaft-and-first-hour-gifts', 1791504000000, 'server', NULL, 'The Praeneste Shaft opens, and the first hour learns to greet you', 'A new mid-ladder mine opened, and the opening hour of a new account now hands you the things a fresh prisoner actually needs.', '{"keyChanges":["The Praeneste Shaft joined the ladder as a new dig site with its own ore table.","The first hour on a new account now greets you with the tools and currency a fresh prisoner actually needs, delivered as you hit early milestones instead of all at once."],"tags":["mines","new-players"],"readHref":"/progression"}', '{}', '[]', NULL)
